"use client";

import { CalendarDays, CheckCircle2, CircleDollarSign, Download, Gift, Plus, RefreshCw, Settings2, ShieldCheck, TrendingUp, UserMinus, WalletCards } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { DataPagination, DataState, DataToolbar, InteractiveTableRow, PageHeading, Table } from "@/app/components/ui/data";
import { Badge, Button, CurrencyInput, Drawer, Field, Input, Modal, Select, Tabs, useToast } from "@/app/components/ui/primitives";
import { PayrollAdjustmentModal, type PayrollAdjustmentKind } from "@/app/components/payroll/PayrollAdjustmentModal";
import { createPayrollPeriodExcel } from "@/app/lib/payroll-report-export";
import { getSupabaseClient } from "@/app/lib/supabase";

type PaymentMethod = "unspecified"|"transfer"|"cash"|"other";
type PayablePaymentMethod = Exclude<PaymentMethod,"unspecified">;
type PositionOption={id:string;code:string;name:string};
type CollaboratorAccess={kind:"user"|"invitation";user_id?:string;invitation_id?:string;email:string;full_name?:string;profile_code:string;profile_name:string;effective_from?:string;created_at?:string};
type Collaborator = { id:string; code:string; display_name:string; job_title:string|null; position_id?:string|null;position_code?:string|null;position_name?:string|null; employment_status:"active"|"inactive"; hired_at:string; terminated_at:string|null; payment_frequency:"weekly"|"biweekly"|"monthly"; base_pay_amount:number|null; effective_from:string|null; payment_method:PaymentMethod };
type Movement = { id:string; collaborator_id:string; movement_type:string; direction:"addition"|"reduction"|"informational"; effective_on:string; units:number|null; amount:number; description:string|null; status:"pending"|"approved"|"rejected"; calculation_metadata?:{hourly_rate?:number;default_hourly_rate?:number;manual_rate_override?:boolean;daily_rate?:number;hours?:number;days?:number;multiplier?:number;paid?:boolean;formula?:string;reported_minutes?:number;payable_hours?:number;double_hours?:number;triple_hours?:number} };
type TimeOff = { id:string; kind:"vacation"|"absence"; starts_on:string; ends_on:string; days:number; status:"pending"|"approved"|"rejected"; affects_payment:boolean; notes:string|null };
type VacationBalance = { calendar_year:number; granted_days:number; adjustment_days:number; used_days:number; notes:string|null };
type PayrollPaymentState = "preparing"|"reviewing"|"due"|"partial"|"paid";
type Period = { id:string; payment_frequency:"weekly"|"biweekly"|"monthly"; starts_on:string; ends_on:string; payment_date:string|null; status:"draft"|"reviewing"|"approved"|"paid"; payment_state?:PayrollPaymentState; has_adjustments?:boolean; notes:string|null; total_pay:number; collaborator_count:number; payment_reference:string|null };
type PeriodConcept = { id:string; concept_code:string; label:string; direction:"addition"|"reduction"|"informational"; amount:number; units:number|null; source_date:string|null; calculation_metadata?:{hourly_rate?:number;default_hourly_rate?:number;manual_rate_override?:boolean;daily_rate?:number;hours?:number;days?:number;multiplier?:number;paid?:boolean;formula?:string;reported_minutes?:number;payable_hours?:number;double_hours?:number;triple_hours?:number} };
type PeriodLine = { id:string; collaborator_id:string; collaborator_name_snapshot:string; base_pay_snapshot:number; additions_total:number; reductions_total:number; total_pay:number; payment_method:PaymentMethod; concepts:PeriodConcept[] };
type PaymentBatch = { id:string;payment_method:PayablePaymentMethod;payment_date:string;payment_reference:string;total_amount:number;recorded_at:string };
type PeriodDetail = Period & { lines:PeriodLine[]; totals:{base_pay:number;additions:number;reductions:number;total_pay:number};payment_batches:PaymentBatch[];approval?:{available_on:string;date_open:boolean;needs_recalculation:boolean;pending_movements:number} };
type Profile = Collaborator & {satrapy_access?:CollaboratorAccess|null; compensation_history:Array<{effective_from:string;base_pay_amount:number;reason:string|null}>; vacation_balances:VacationBalance[]; time_off:TimeOff[]; movements:Movement[]; payroll_history:Array<{id:string;base_pay_snapshot:number;additions_total:number;reductions_total:number;total_pay:number;period_start:string;period_end:string;period_status:string;payment_date:string|null}> };
type CollaboratorDraft = { id?:string;code:string;displayName:string;jobTitle:string;positionId:string;status:"active"|"inactive";hiredAt:string;terminatedAt:string;frequency:"weekly"|"biweekly"|"monthly";basePay:string;effectiveFrom:string;reason:string };
type AccessDraft={collaboratorId:string;collaboratorName:string;email:string;profileCode:string;locationIds:string[];reason:string;clientRequestId:string};
type AccessOptions={roles:Array<{code:string;name:string;description:string}>;locations:Array<{id:string;code:string;name:string}>};
type MovementDraft = { collaboratorId:string; movementType:string; direction:"addition"|"reduction"|"informational";effectiveOn:string;units:string;amount:string;description:string;approve:boolean };
type TimeOffDraft = { collaboratorId:string;kind:"vacation"|"absence";startsOn:string;endsOn:string;days:string;affectsPayment:boolean;notes:string;approve:boolean };
type PayrollSchedule = { payment_frequency:"weekly"|"biweekly"|"monthly" };
type OperationalSettings = { payable_days_per_period:number|null;hours_per_workday:number|null;default_overtime_hourly_rate:number|null };
type CurrentPeriod = { period:Period|null; proposed:{payment_frequency:"weekly"|"biweekly"|"monthly";starts_on:string;ends_on:string;payment_date:string|null} };
type VacationBalanceDraft = { collaboratorId:string;year:string;grantedDays:string;adjustmentDays:string;notes:string };
type TerminationDraft = { collaboratorId:string;displayName:string;hiredAt:string;terminatedAt:string;reason:string };
type OperationalSettingsDraft = { payableDays:string;hoursPerWorkday:string;defaultOvertimeHourlyRate:string };
type PaymentMethodDraft = { collaboratorId:string;paymentMethod:PaymentMethod };
type PayrollLinePaymentMethodDraft = { lineId:string;collaboratorName:string;paymentMethod:PayablePaymentMethod };
type PaymentBatchDraft = { paymentMethod:PayablePaymentMethod;paymentDate:string;reference:string };
type PayrollPreflight = { included:number;missing_compensation:number;pending_movements:number;approved_movements:number;estimated_total:number };
type PendingIncident = { id:string;collaborator_id:string;collaborator_code:string;collaborator_name:string;movement_type:PayrollAdjustmentKind;effective_on:string;amount:number;units:number|null;description:string|null;calculation_metadata:{hourly_rate?:number;default_hourly_rate?:number;manual_rate_override?:boolean;daily_rate?:number;hours?:number;days?:number;multiplier?:number;paid?:boolean;formula?:string;reported_minutes?:number;payable_hours?:number;double_hours?:number;triple_hours?:number};starts_on:string|null;ends_on:string|null;days:number|null;paid:boolean|null };
type PendingIncidentsPage = { items:PendingIncident[];pagination:{page:number;page_size:number;total:number} };
type PayrollWorkspaceLine = { id:string;code:string;display_name:string;base_pay:number;overtime:number;absences:number;commissions:number;bonuses:number;pending_count:number;estimated_pay:number };
type PayrollWorkspace = { period:{payment_frequency:"weekly"|"biweekly"|"monthly";starts_on:string;ends_on:string};items:PayrollWorkspaceLine[];summary:{base_pay:number;overtime:number;absences:number;commissions:number;bonuses:number;estimated_pay:number;pending_count:number};pagination:{page:number;page_size:number;total:number} };

const pageSize=50;
const frequencyLabel:Record<string,string>={weekly:"Semanal",biweekly:"Quincenal",monthly:"Mensual"};
const statusLabel:Record<string,string>={draft:"Preparar",reviewing:"En revisión",approved:"Aprobada",paid:"Pagada",pending:"Pendiente",active:"Activo",inactive:"Inactivo",approved_movement:"Aprobado"};
const payrollPaymentStateLabel:Record<PayrollPaymentState,string>={preparing:"En preparación",reviewing:"En revisión",due:"Nómina por pagar",partial:"Pago parcial",paid:"Nómina pagada"};
const paymentMethodLabel:Record<PaymentMethod,string>={unspecified:"Sin definir",transfer:"Transferencia",cash:"Efectivo",other:"Otro"};
const money=(value:number|null|undefined)=>new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN"}).format(Number(value??0));
const date=(value:string|null|undefined)=>value?new Intl.DateTimeFormat("es-MX",{dateStyle:"medium"}).format(new Date(`${value}T12:00:00`)):"—";
const previousDate=(value:string)=>{const result=new Date(`${value}T12:00:00Z`);result.setUTCDate(result.getUTCDate()-1);return result.toISOString().slice(0,10);};
const calculationLabel=(item:Pick<PeriodConcept,"concept_code"|"calculation_metadata">)=>{const calculation=item.calculation_metadata;if(!calculation)return "";if(item.concept_code==="overtime"&&calculation.hourly_rate!==undefined){const hours=calculation.payable_hours??calculation.hours??0;return `${hours} h × ${money(calculation.hourly_rate)}/h${calculation.manual_rate_override?" · tarifa individual":""}`;}if(item.concept_code==="absence"){const days=calculation.days??0;const hours=calculation.hours??0;return `${days} días · ${hours} horas`;}return "";};
const conceptAmount=(line:PeriodLine,code:string)=>line.concepts.filter(item=>item.concept_code===code).reduce((sum,item)=>sum+Number(item.amount),0);
const tone=(status:string):"success"|"warning"|"neutral"=>status==="paid"||status==="approved"||status==="active"?"success":status==="reviewing"||status==="pending"||status==="draft"?"warning":"neutral";
const payrollPresentation=(period:Pick<Period,"status"|"payment_state"|"has_adjustments">)=>{const fallbackState:PayrollPaymentState=period.status==="paid"?"paid":period.status==="approved"?"due":period.status==="reviewing"?"reviewing":"preparing";const paymentState=period.payment_state??fallbackState;return {label:`${payrollPaymentStateLabel[paymentState]}${period.has_adjustments?" · Con ajustes":""}`,tone:paymentState==="paid"?"success" as const:paymentState==="due"||paymentState==="partial"||paymentState==="preparing"||paymentState==="reviewing"?"warning" as const:"neutral" as const};};
const formatMoneyInput=(value:string)=>{const [whole,decimal]=value.replace(/[^\d.]/g,"").split(".",2);const formatted=(whole||"").replace(/\B(?=(\d{3})+(?!\d))/g,",");return decimal===undefined?formatted:`${formatted}.${decimal}`;};
const emptyCollaborator=():CollaboratorDraft=>({code:"",displayName:"",jobTitle:"",positionId:"",status:"active",hiredAt:new Date().toISOString().slice(0,10),terminatedAt:"",frequency:"weekly",basePay:"",effectiveFrom:new Date().toISOString().slice(0,10),reason:""});
const emptyMovement=(collaboratorId=""):MovementDraft=>({collaboratorId,movementType:"bonus",direction:"addition",effectiveOn:new Date().toISOString().slice(0,10),units:"",amount:"",description:"",approve:true});
const emptyTimeOff=(collaboratorId=""):TimeOffDraft=>({collaboratorId,kind:"vacation",startsOn:new Date().toISOString().slice(0,10),endsOn:new Date().toISOString().slice(0,10),days:"",affectsPayment:false,notes:"",approve:true});
const emptyVacationBalance=(collaboratorId:string,current?:VacationBalance):VacationBalanceDraft=>({collaboratorId,year:String(current?.calendar_year??new Date().getFullYear()),grantedDays:String(current?.granted_days??""),adjustmentDays:String(current?.adjustment_days??0),notes:current?.notes??""});
const emptyTermination=(profile:Profile):TerminationDraft=>({collaboratorId:profile.id,displayName:profile.display_name,hiredAt:profile.hired_at,terminatedAt:new Date().toISOString().slice(0,10),reason:""});
const operationalDraftFrom=(settings:OperationalSettings):OperationalSettingsDraft=>({payableDays:settings.payable_days_per_period===null?"":String(settings.payable_days_per_period),hoursPerWorkday:settings.hours_per_workday===null?"":String(settings.hours_per_workday),defaultOvertimeHourlyRate:Number(settings.default_overtime_hourly_rate??50).toFixed(2)});
const emptyPaymentBatch=(paymentMethod:PayablePaymentMethod):PaymentBatchDraft=>({paymentMethod,paymentDate:new Date().toISOString().slice(0,10),reference:""});

export function CollaboratorsDirectoryView({companyId,permissions}:{companyId:string;permissions:string[]}) {
  const {toast}=useToast(); const [rows,setRows]=useState<Collaborator[]>([]);const [total,setTotal]=useState(0);const [page,setPage]=useState(1);const [query,setQuery]=useState("");const [debounced,setDebounced]=useState("");const [status,setStatus]=useState("active");const [loading,setLoading]=useState(true);const [error,setError]=useState<string|null>(null);const [draft,setDraft]=useState<CollaboratorDraft|null>(null);const [profile,setProfile]=useState<Profile|null>(null);const [profileTab,setProfileTab]=useState("labor");const [movement,setMovement]=useState<MovementDraft|null>(null);const [timeOff,setTimeOff]=useState<TimeOffDraft|null>(null);const [vacationBalance,setVacationBalance]=useState<VacationBalanceDraft|null>(null);const [termination,setTermination]=useState<TerminationDraft|null>(null);const [paymentMethod,setPaymentMethod]=useState<PaymentMethodDraft|null>(null);const [positions,setPositions]=useState<PositionOption[]>([]);const [access,setAccess]=useState<AccessDraft|null>(null);const [accessOptions,setAccessOptions]=useState<AccessOptions|null>(null);const [saving,setSaving]=useState(false);const request=useRef(0);
  const canManage=permissions.includes("manage_collaborators");const canMove=permissions.includes("manage_payroll_movements");const canManageAccess=canManage&&permissions.includes("manage_company_users");
  useEffect(()=>{const timer=window.setTimeout(()=>{setDebounced(query.trim());setPage(1);},250);return()=>window.clearTimeout(timer);},[query]);
  useEffect(()=>{void getSupabaseClient().rpc("get_collaborator_position_options",{p_company_id:companyId}).then(({data,error:rpcError})=>{if(rpcError){setError(rpcError.message);return;}setPositions((data as PositionOption[]|null)??[]);});},[companyId]);
  const load=useCallback(async()=>{const current=++request.current;setLoading(true);setError(null);const {data,error:rpcError}=await getSupabaseClient().rpc("search_collaborators",{p_company_id:companyId,p_query:debounced||null,p_status:status||null,p_page:page,p_page_size:pageSize});if(current!==request.current)return;const result=data as {items?:Collaborator[];pagination?:{total:number}}|null;setRows(result?.items??[]);setTotal(result?.pagination?.total??0);setError(rpcError?.message??null);setLoading(false);},[companyId,debounced,page,status]);
  useEffect(()=>{void Promise.resolve().then(load);},[load]);
  const openProfile=useCallback(async(id:string)=>{setProfile(null);setProfileTab("labor");const {data,error:rpcError}=await getSupabaseClient().rpc("get_collaborator_profile",{p_company_id:companyId,p_collaborator_id:id});if(rpcError){toast({title:"No se pudo abrir el colaborador",description:rpcError.message,tone:"error"});return;}setProfile(data as Profile);},[companyId,toast]);
  async function saveCollaborator(){if(!draft)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("save_collaborator",{p_company_id:companyId,p_collaborator_id:draft.id??null,p_code:draft.code,p_display_name:draft.displayName,p_job_title:draft.jobTitle,p_position_id:draft.positionId||null,p_employment_status:draft.status,p_hired_at:draft.hiredAt,p_terminated_at:draft.terminatedAt||null,p_payment_frequency:draft.frequency,p_base_pay_amount:Number(draft.basePay.replace(/,/g,"")),p_effective_from:draft.effectiveFrom,p_reason:draft.reason});setSaving(false);if(rpcError){toast({title:"No se guardó el colaborador",description:rpcError.message,tone:"error"});return;}setDraft(null);setProfile(data as Profile);await load();toast({title:"Colaborador guardado",description:"El puesto y el historial de sueldo conservan su vigencia.",tone:"success"});}
  async function saveMovement(){if(!movement)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_payroll_movements_batch",{p_company_id:companyId,p_movements:[{collaborator_id:movement.collaboratorId,movement_type:movement.movementType,direction:movement.direction,effective_on:movement.effectiveOn,units:movement.units||null,amount:Number(movement.amount||0),description:movement.description}],p_approve:movement.approve});setSaving(false);if(rpcError){toast({title:"No se guardó el movimiento",description:rpcError.message,tone:"error"});return;}const collaboratorId=movement.collaboratorId;setMovement(null);await openProfile(collaboratorId);toast({title:"Movimiento registrado",description:movement.approve?"Quedó aprobado para la siguiente nómina.":"Quedó pendiente de aprobación.",tone:"success"});}
  async function saveTimeOff(){if(!timeOff)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_collaborator_time_off",{p_company_id:companyId,p_time_off_id:null,p_collaborator_id:timeOff.collaboratorId,p_kind:timeOff.kind,p_starts_on:timeOff.startsOn,p_ends_on:timeOff.endsOn,p_days:Number(timeOff.days),p_affects_payment:timeOff.affectsPayment,p_notes:timeOff.notes,p_approve:timeOff.approve});setSaving(false);if(rpcError){toast({title:"No se guardó la ausencia",description:rpcError.message,tone:"error"});return;}const collaboratorId=timeOff.collaboratorId;setTimeOff(null);await openProfile(collaboratorId);toast({title:timeOff.kind==="vacation"?"Vacaciones registradas":"Ausencia registrada",description:timeOff.approve?"Quedó aprobada.":"Quedó pendiente de aprobación.",tone:"success"});}
  async function saveVacationBalance(){if(!vacationBalance)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_collaborator_vacation_balance",{p_company_id:companyId,p_collaborator_id:vacationBalance.collaboratorId,p_calendar_year:Number(vacationBalance.year),p_granted_days:Number(vacationBalance.grantedDays),p_adjustment_days:Number(vacationBalance.adjustmentDays||0),p_notes:vacationBalance.notes});setSaving(false);if(rpcError){toast({title:"No se guardó el saldo",description:rpcError.message,tone:"error"});return;}const collaboratorId=vacationBalance.collaboratorId;setVacationBalance(null);await openProfile(collaboratorId);toast({title:"Saldo de vacaciones actualizado",description:"Los días usados se conservan desde las vacaciones aprobadas.",tone:"success"});}
  async function terminateCollaborator(){if(!termination)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("terminate_collaborator",{p_company_id:companyId,p_collaborator_id:termination.collaboratorId,p_terminated_at:termination.terminatedAt,p_reason:termination.reason});setSaving(false);if(rpcError){toast({title:"No se dio de baja al colaborador",description:rpcError.message,tone:"error"});return;}setTermination(null);setProfile(data as Profile);await load();toast({title:"Colaborador dado de baja",description:"Conserva su expediente e historial; no entrará en periodos posteriores.",tone:"success"});}
  async function savePaymentMethod(){if(!paymentMethod)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("save_collaborator_payment_method",{p_company_id:companyId,p_collaborator_id:paymentMethod.collaboratorId,p_payment_method:paymentMethod.paymentMethod});setSaving(false);if(rpcError){toast({title:"No se guardó la forma de pago",description:rpcError.message,tone:"error"});return;}setPaymentMethod(null);setProfile(data as Profile);toast({title:"Forma de pago actualizada",description:"Se usará como predeterminada en las siguientes corridas.",tone:"success"});}
  async function openAccess(value:Profile){const {data,error:rpcError}=await getSupabaseClient().rpc("get_company_user_access_options",{p_company_id:companyId});if(rpcError){toast({title:"No se pudo preparar el acceso",description:rpcError.message,tone:"error"});return;}const options=data as AccessOptions;setAccessOptions(options);const suggested=value.position_code==="ingeniero_campo"?"ingeniero_campo":options.roles[0]?.code??"";setAccess({collaboratorId:value.id,collaboratorName:value.display_name,email:"",profileCode:suggested,locationIds:[],reason:"Alta de acceso autorizada desde el expediente.",clientRequestId:crypto.randomUUID()});}
  function toggleAccessLocation(id:string){setAccess(current=>current?{...current,locationIds:current.locationIds.includes(id)?current.locationIds.filter(item=>item!==id):[...current.locationIds,id]}:current);}
  async function saveAccess(){if(!access)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("provision_collaborator_user_access",{p_company_id:companyId,p_collaborator_id:access.collaboratorId,p_email:access.email,p_profile_code:access.profileCode,p_location_ids:access.locationIds,p_reason:access.reason,p_client_request_id:access.clientRequestId});setSaving(false);if(rpcError){toast({title:"No se otorgó el acceso",description:rpcError.message,tone:"error"});return;}const collaboratorId=access.collaboratorId;setAccess(null);await openProfile(collaboratorId);toast({title:"Acceso preparado",description:"La cuenta y el colaborador quedaron vinculados; si aún no existe cuenta, quedó autorizada para registrarse.",tone:"success"});}
  const editDraft=(value:Profile):CollaboratorDraft=>({id:value.id,code:value.code,displayName:value.display_name,jobTitle:value.job_title??"",positionId:value.position_id??"",status:value.employment_status,hiredAt:value.hired_at,terminatedAt:value.terminated_at??"",frequency:value.payment_frequency,basePay:formatMoneyInput(String(value.compensation_history[0]?.base_pay_amount??value.base_pay_amount??"")),effectiveFrom:new Date().toISOString().slice(0,10),reason:"Actualización de pago"});
  return <div className="content-frame collaborator-module">
    <PageHeading eyebrow="Colaboradores" title="Directorio" description="Expediente laboral, vacaciones y movimientos que alimentan la nómina." action={canManage?<Button variant="primary" onClick={()=>setDraft(emptyCollaborator())}><Plus size={16}/>Nuevo colaborador</Button>:undefined}/>
    <DataToolbar search={query} onSearchChange={setQuery} placeholder="Buscar por nombre, código o puesto" results={total} filters={<Select ariaLabel="Estado de colaborador" value={status||"all"} onValueChange={value=>{setStatus(value==="all"?"":value);setPage(1);}} options={[{value:"all",label:"Todos"},{value:"active",label:"Activos"},{value:"inactive",label:"Inactivos"}]}/>}/>
    <DataState loading={loading} error={error} hasData={rows.length} empty={canManage?"Crea el primer colaborador para comenzar.":"Tu perfil sólo permite consultar colaboradores."} emptyAction={canManage?<Button size="sm" onClick={()=>setDraft(emptyCollaborator())}>Crear colaborador</Button>:undefined}>
      <Table><thead><tr><th>Colaborador</th><th>Puesto</th><th>Pago base</th><th>Periodicidad</th><th>Ingreso</th><th>Estado</th></tr></thead><tbody>{rows.map(row=><InteractiveTableRow key={row.id} label={`Abrir ${row.display_name}`} onActivate={()=>void openProfile(row.id)}><td><strong>{row.display_name}</strong><small>{row.code}</small></td><td>{row.position_name??row.job_title??"Sin clasificar"}</td><td>{row.base_pay_amount===null?"Sin sueldo vigente":money(row.base_pay_amount)}</td><td>{frequencyLabel[row.payment_frequency]}</td><td>{date(row.hired_at)}</td><td><Badge tone={row.employment_status==="active"?"success":"neutral"}>{statusLabel[row.employment_status]}</Badge></td></InteractiveTableRow>)}</tbody></Table>
      <DataPagination page={page} onChange={setPage} total={total} pageSize={pageSize} label="colaboradores"/>
    </DataState>
    <Drawer open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&setDraft(null)} title={draft?.id?"Editar colaborador":"Nuevo colaborador"} className="collaborator-drawer">{draft&&<form className="drawer-form" onSubmit={event=>{event.preventDefault();void saveCollaborator();}}>
      <section>
        <h3>Datos laborales</h3>
        {!draft.id&&<p>Satrapy asignará el código automáticamente al guardar.</p>}
        <div className="form-grid">
          <Field label="Nombre completo"><Input required value={draft.displayName} onChange={event=>setDraft({...draft,displayName:event.target.value})}/></Field>
          <Field label="Puesto" hint={draft.jobTitle&&!draft.positionId?`Importado sin clasificar: ${draft.jobTitle}`:"El puesto laboral no concede permisos por sí solo."}><Select ariaLabel="Puesto del colaborador" value={draft.positionId} onValueChange={value=>setDraft({...draft,positionId:value})} placeholder="Selecciona un puesto" options={positions.map(position=>({value:position.id,label:position.name}))}/></Field>
          <Field label="Fecha de ingreso"><Input required type="date" value={draft.hiredAt} onChange={event=>setDraft({...draft,hiredAt:event.target.value,...(!draft.id?{effectiveFrom:event.target.value}: {})})}/></Field>
        </div>
      </section>
      <section>
        <h3>Pago</h3>
        <p>Define el importe y la periodicidad del colaborador.</p>
        <div className="form-grid">
          <Field label="Periodicidad"><Select ariaLabel="Periodicidad" value={draft.frequency} onValueChange={value=>setDraft({...draft,frequency:value as CollaboratorDraft["frequency"]})} options={[{value:"weekly",label:"Semanal"},{value:"biweekly",label:"Quincenal"},{value:"monthly",label:"Mensual"}]}/></Field>
          <Field label="Pago base"><Input required inputMode="decimal" value={draft.basePay} onChange={event=>setDraft({...draft,basePay:formatMoneyInput(event.target.value)})}/></Field>
          {draft.id&&<Field label="Vigente desde"><Input required type="date" value={draft.effectiveFrom} onChange={event=>setDraft({...draft,effectiveFrom:event.target.value})}/></Field>}
          {draft.id&&<Field label="Motivo del cambio"><Input required value={draft.reason} onChange={event=>setDraft({...draft,reason:event.target.value})} placeholder="Describe la actualización"/></Field>}
        </div>
      </section>
      <div className="drawer-actions"><Button onClick={()=>setDraft(null)} disabled={saving}>Cancelar</Button><Button type="submit" variant="primary" loading={saving}>Guardar colaborador</Button></div>
    </form>}</Drawer>
    <Drawer open={Boolean(profile)} onOpenChange={open=>!open&&setProfile(null)} title={profile?.display_name??"Colaborador"} className="collaborator-profile">{profile&&<><div className="collaborator-profile__summary"><span>{profile.code}</span><strong>{profile.position_name??profile.job_title??"Sin puesto clasificado"}</strong><Badge tone={profile.employment_status==="active"?"success":"neutral"}>{statusLabel[profile.employment_status]}</Badge></div><Tabs value={profileTab} onValueChange={setProfileTab} items={[{value:"labor",label:"Laboral"},{value:"access",label:"Acceso a Satrapy"},{value:"time",label:"Vacaciones"},{value:"movements",label:"Movimientos"},{value:"history",label:"Pagos"}]}/>{profileTab==="labor"&&<div className="profile-section"><div className="profile-metric"><span>Pago vigente</span><strong>{money(profile.compensation_history[0]?.base_pay_amount??profile.base_pay_amount)}</strong><small>{frequencyLabel[profile.payment_frequency]} · vigente desde {date(profile.compensation_history[0]?.effective_from)}</small></div><div className="profile-grid"><div><span>Ingreso</span><strong>{date(profile.hired_at)}</strong></div><div><span>Forma de pago</span><strong>{paymentMethodLabel[profile.payment_method??"unspecified"]}</strong></div><div><span>Baja</span><strong>{date(profile.terminated_at)}</strong></div></div><h3>Historial salarial</h3><ul className="history-list">{profile.compensation_history.map(entry=><li key={entry.effective_from}><span>{date(entry.effective_from)}</span><strong>{money(entry.base_pay_amount)}</strong><small>{entry.reason??"Sin observación"}</small></li>)}</ul>{canManage&&<div className="profile-section__actions"><Button variant="secondary" onClick={()=>setDraft(editDraft(profile))}>Editar datos laborales</Button><Button variant="secondary" onClick={()=>setPaymentMethod({collaboratorId:profile.id,paymentMethod:profile.payment_method??"unspecified"})}>Forma de pago</Button>{profile.employment_status==="active"&&<Button variant="danger" onClick={()=>setTermination(emptyTermination(profile))}><UserMinus size={15}/>Dar de baja</Button>}</div>}</div>}{profileTab==="access"&&<div className="profile-section"><div className="profile-section__header"><div><h3>Acceso a Satrapy</h3><p>La cuenta se vincula a este expediente; el perfil de acceso define lo que puede hacer dentro de Satrapy.</p></div>{canManageAccess&&!profile.satrapy_access&&profile.employment_status==="active"&&<Button size="sm" variant="primary" onClick={()=>void openAccess(profile)}><ShieldCheck size={15}/>Dar acceso a Satrapy</Button>}</div>{profile.satrapy_access?<div className="profile-metric"><span>{profile.satrapy_access.kind==="invitation"?"Registro autorizado":"Cuenta vinculada"}</span><strong>{profile.satrapy_access.email}</strong><small>{profile.satrapy_access.profile_name}{profile.satrapy_access.effective_from?` · vigente desde ${date(profile.satrapy_access.effective_from)}`:" · pendiente de registro"}</small></div>:<p>{canManageAccess?"Aún no tiene una cuenta vinculada.":"Sólo quien administra Colaboradores y Usuarios puede otorgar acceso."}</p>}</div>}{profileTab==="time"&&<div className="profile-section"><div className="profile-section__header"><div><h3>Vacaciones y ausencias</h3><p>Registra vacaciones aquí. Las inasistencias que afectan la nómina se capturan desde Nómina → Inasistencias.</p></div>{canMove&&<div className="profile-section__actions"><Button size="sm" variant="secondary" onClick={()=>setVacationBalance(emptyVacationBalance(profile.id,profile.vacation_balances.find(item=>item.calendar_year===new Date().getFullYear())))}>Ajustar saldo</Button><Button size="sm" variant="primary" onClick={()=>setTimeOff(emptyTimeOff(profile.id))}><CalendarDays size={15}/>Registrar vacaciones</Button></div>}</div><div className="vacation-balances">{profile.vacation_balances.length?profile.vacation_balances.map(balance=><article key={balance.calendar_year}><span>{balance.calendar_year}</span><strong>{Number(balance.granted_days)+Number(balance.adjustment_days)-Number(balance.used_days)} días</strong><small>{balance.used_days} usados</small></article>):<p>Aún no hay saldo de vacaciones registrado.</p>}</div><ul className="history-list">{profile.time_off.map(item=><li key={item.id}><span>{item.kind==="vacation"?"Vacaciones":"Ausencia"}</span><strong>{date(item.starts_on)} – {date(item.ends_on)} · {item.days} días</strong><Badge tone={item.status==="approved"?"success":"warning"}>{item.status==="approved"?"Aprobado":"Pendiente"}</Badge></li>)}</ul></div>}{profileTab==="movements"&&<div className="profile-section"><div className="profile-section__header"><div><h3>Movimientos de nómina</h3><p>Bonos, aguinaldo, prima vacacional y ajustes aprobados se incorporan a la siguiente corrida aplicable.</p></div>{canMove&&<Button size="sm" variant="primary" onClick={()=>setMovement(emptyMovement(profile.id))}><Plus size={15}/>Registrar otro concepto</Button>}</div><ul className="history-list">{profile.movements.map(item=><li key={item.id}><span>{movementLabel(item.movement_type)}</span><strong className={item.direction==="reduction"?"is-reduction":""}>{item.direction==="reduction"?"−":item.direction==="addition"?"+":""}{money(item.amount)}</strong><small>{date(item.effective_on)}{item.units?` · ${item.units} unidades`:""}{item.description?` · ${item.description}`:""}</small><Badge tone={item.status==="approved"?"success":"warning"}>{item.status==="approved"?"Aprobado":"Pendiente"}</Badge></li>)}</ul></div>}{profileTab==="history"&&<div className="profile-section"><h3>Historial de pagos</h3><ul className="history-list">{profile.payroll_history.map(item=><li key={item.id}><span>{date(item.period_start)} – {date(item.period_end)}</span><strong>{money(item.total_pay)}</strong><small>Base {money(item.base_pay_snapshot)} · Extras {money(item.additions_total)} · Ajustes {money(item.reductions_total)}</small><Badge tone={tone(item.period_status)}>{statusLabel[item.period_status]}</Badge></li>)}</ul></div>}</>}</Drawer>
    <PaymentMethodModal draft={paymentMethod} saving={saving} onChange={setPaymentMethod} onClose={()=>setPaymentMethod(null)} onSave={()=>void savePaymentMethod()}/>
    <MovementModal draft={movement} saving={saving} onChange={setMovement} onClose={()=>setMovement(null)} onSave={()=>void saveMovement()}/><TimeOffModal draft={timeOff} saving={saving} onChange={setTimeOff} onClose={()=>setTimeOff(null)} onSave={()=>void saveTimeOff()}/><VacationBalanceModal draft={vacationBalance} saving={saving} onChange={setVacationBalance} onClose={()=>setVacationBalance(null)} onSave={()=>void saveVacationBalance()}/><TerminationModal draft={termination} saving={saving} onChange={setTermination} onClose={()=>setTermination(null)} onSave={()=>void terminateCollaborator()}/>
    <CollaboratorAccessModal draft={access} options={accessOptions} saving={saving} onChange={setAccess} onToggleLocation={toggleAccessLocation} onClose={()=>setAccess(null)} onSave={()=>void saveAccess()}/>
  </div>;
}

function CollaboratorAccessModal({draft,options,saving,onChange,onToggleLocation,onClose,onSave}:{draft:AccessDraft|null;options:AccessOptions|null;saving:boolean;onChange:(draft:AccessDraft|null)=>void;onToggleLocation:(id:string)=>void;onClose:()=>void;onSave:()=>void}){if(!draft||!options)return null;const scoped=draft.profileCode==="sucursal"||draft.profileCode==="ingeniero_campo";const profile=options.roles.find(item=>item.code===draft.profileCode);const canSave=Boolean(draft.email.trim()&&draft.profileCode&&draft.reason.trim()&&(!scoped||draft.locationIds.length));return <Modal open onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Acceso a Satrapy" title={`Dar acceso a ${draft.collaboratorName}`} description="La cuenta queda vinculada a este expediente. El puesto identifica a la persona; el perfil define sus permisos." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!canSave} onClick={onSave}>Autorizar acceso</Button></>}><div className="drawer-form"><Field label="Correo autorizado"><Input type="email" value={draft.email} onChange={event=>onChange({...draft,email:event.target.value})} placeholder="persona@empresa.com"/></Field><Field label="Perfil de acceso" hint={profile?.description}><Select ariaLabel="Perfil de acceso" value={draft.profileCode} onValueChange={value=>onChange({...draft,profileCode:value,locationIds:[]})} options={options.roles.map(role=>({value:role.code,label:role.name}))}/></Field>{scoped&&<Field label="Sucursales autorizadas" hint="Define dónde podrá operar esta cuenta."><div className="user-location-picker">{options.locations.map(location=><label key={location.id}><input type="checkbox" checked={draft.locationIds.includes(location.id)} onChange={()=>onToggleLocation(location.id)}/><span><strong>{location.name}</strong><small>{location.code}</small></span></label>)}</div></Field>}<Field label="Motivo" hint="Se conserva en auditoría"><Input value={draft.reason} onChange={event=>onChange({...draft,reason:event.target.value})} placeholder="Ej. Alta autorizada para operación comercial"/></Field></div></Modal>}

export function PayrollView({companyId,permissions}:{companyId:string;permissions:string[]}) {
  const {toast}=useToast();
  const activeAdjustmentKey=`satrapy:payroll-adjustment:active:${companyId}`;
  const [rows,setRows]=useState<Period[]>([]);const [total,setTotal]=useState(0);const [page,setPage]=useState(1);const [loading,setLoading]=useState(true);const [error,setError]=useState<string|null>(null);
  const [schedule,setSchedule]=useState<PayrollSchedule>({payment_frequency:"weekly"});const [settings,setSettings]=useState<OperationalSettings>({payable_days_per_period:null,hours_per_workday:null,default_overtime_hourly_rate:50});const [settingsDraft,setSettingsDraft]=useState<OperationalSettingsDraft>({payableDays:"",hoursPerWorkday:"",defaultOvertimeHourlyRate:"50.00"});const [scheduleOpen,setScheduleOpen]=useState(false);
  const [current,setCurrent]=useState<CurrentPeriod|null>(null);const [preflight,setPreflight]=useState<PayrollPreflight|null>(null);const [detail,setDetail]=useState<PeriodDetail|null>(null);const [adjustmentKind,setAdjustmentKind]=useState<PayrollAdjustmentKind|null>(()=>{if(typeof window==="undefined")return null;const stored=window.sessionStorage.getItem(activeAdjustmentKey);return stored==="overtime"||stored==="absence"||stored==="commission"||stored==="bonus"?stored:null;});const [workspace,setWorkspace]=useState<PayrollWorkspace|null>(null);const [workspacePage,setWorkspacePage]=useState(1);const [workspaceQuery,setWorkspaceQuery]=useState("");const [workspaceDebounced,setWorkspaceDebounced]=useState("");const [pendingIncidents,setPendingIncidents]=useState<PendingIncident[]>([]);const [pendingIncidentsTotal,setPendingIncidentsTotal]=useState(0);const [pendingIncidentsPage,setPendingIncidentsPage]=useState(1);const [pendingOpen,setPendingOpen]=useState(false);const [selectedIncidents,setSelectedIncidents]=useState<string[]>([]);const [linePaymentMethod,setLinePaymentMethod]=useState<PayrollLinePaymentMethodDraft|null>(null);const [paymentBatch,setPaymentBatch]=useState<PaymentBatchDraft|null>(null);const [saving,setSaving]=useState(false);
  const canManage=permissions.includes("manage_payroll_runs");const canMove=permissions.includes("manage_payroll_movements");const canApprove=permissions.includes("approve_payroll_runs");const canPay=permissions.includes("mark_payroll_paid");
  const incidentsReady=Boolean(settings.payable_days_per_period&&settings.hours_per_workday&&settings.default_overtime_hourly_rate);
  useEffect(()=>{const timer=window.setTimeout(()=>{setWorkspaceDebounced(workspaceQuery.trim());setWorkspacePage(1);},250);return()=>window.clearTimeout(timer);},[workspaceQuery]);
  const load=useCallback(async()=>{
    setLoading(true);setError(null)
    const client=getSupabaseClient()
    const [periods,scheduleResult,currentResult,preflightResult,settingsResult,pendingResult,workspaceResult]=await Promise.all([
      client.rpc("search_payroll_periods",{p_company_id:companyId,p_page:page,p_page_size:pageSize}),
      client.rpc("get_payroll_schedule",{p_company_id:companyId}),
      client.rpc("get_current_payroll_period",{p_company_id:companyId}),
      client.rpc("get_payroll_preflight",{p_company_id:companyId}),
      client.rpc("get_payroll_operational_settings",{p_company_id:companyId}),
      client.rpc("get_pending_payroll_incidents",{p_company_id:companyId,p_page:pendingIncidentsPage,p_page_size:100}),
      client.rpc("get_payroll_workspace",{p_company_id:companyId,p_query:workspaceDebounced||null,p_page:workspacePage,p_page_size:50}),
    ])
    const result=periods.data as {items?:Period[];pagination?:{total:number}}|null
    const pending=pendingResult.data as PendingIncidentsPage|null
    let nextWorkspace=(workspaceResult.data as PayrollWorkspace|null)??null
    let workspaceError=workspaceResult.error?.message??null

    // Mantiene visible la mesa durante un despliegue escalonado. Guardar ajustes
    // sí exige el RPC transaccional nuevo y nunca cae en una escritura parcial.
    if(!nextWorkspace){
      const fallback=await client.rpc("search_collaborators",{p_company_id:companyId,p_query:workspaceDebounced||null,p_status:"active",p_page:workspacePage,p_page_size:50})
      const period=((currentResult.data as CurrentPeriod|null)?.period??(currentResult.data as CurrentPeriod|null)?.proposed)??null
      if(!fallback.error&&period){
        const fallbackRows:PayrollWorkspaceLine[]=((fallback.data as {items?:Collaborator[];pagination?:{total:number}}|null)?.items??[]).map((collaborator)=>{
          const basePay=Number(collaborator.base_pay_amount??0)
          return {id:collaborator.id,code:collaborator.code,display_name:collaborator.display_name,base_pay:basePay,overtime:0,absences:0,commissions:0,bonuses:0,pending_count:0,estimated_pay:basePay}
        })
        const baseTotal=fallbackRows.reduce((total,item)=>total+item.base_pay,0)
        nextWorkspace={
          period:{payment_frequency:period.payment_frequency,starts_on:period.starts_on,ends_on:period.ends_on},
          items:fallbackRows,
          summary:{base_pay:baseTotal,overtime:0,absences:0,commissions:0,bonuses:0,estimated_pay:baseTotal,pending_count:0},
          pagination:{page:workspacePage,page_size:50,total:Number((fallback.data as {pagination?:{total:number}}|null)?.pagination?.total??fallbackRows.length)},
        }
        workspaceError=null
      }else{
        workspaceError=fallback.error?.message??workspaceError
      }
    }

    setRows(result?.items??[]);setTotal(result?.pagination?.total??0)
    setSchedule((scheduleResult.data as PayrollSchedule|null)??{payment_frequency:"weekly"})
    setCurrent(currentResult.data as CurrentPeriod|null)
    setPreflight(preflightResult.data as PayrollPreflight|null)
    const loadedSettings=(settingsResult.data as OperationalSettings|null)??{payable_days_per_period:null,hours_per_workday:null,default_overtime_hourly_rate:50}
    setSettings({...loadedSettings,default_overtime_hourly_rate:loadedSettings.default_overtime_hourly_rate??50})
    setPendingIncidents(pending?.items??[]);setPendingIncidentsTotal(pending?.pagination?.total??0)
    setWorkspace(nextWorkspace)
    setError(periods.error?.message??scheduleResult.error?.message??currentResult.error?.message??preflightResult.error?.message??workspaceError)
    setLoading(false)
  },[companyId,page,pendingIncidentsPage,workspaceDebounced,workspacePage]);useEffect(()=>{void Promise.resolve().then(load);},[load]);
  const openDetail=useCallback(async(id:string)=>{const {data,error:rpcError}=await getSupabaseClient().rpc("get_payroll_period",{p_company_id:companyId,p_period_id:id});if(rpcError){toast({title:"No se pudo abrir la nómina",description:rpcError.message,tone:"error"});return;}setDetail(data as PeriodDetail);},[companyId,toast]);
  function openSettings(){setSettingsDraft(operationalDraftFrom(settings));setScheduleOpen(true);}
  function openAdjustmentCapture(kind:PayrollAdjustmentKind){if(!incidentsReady){toast({title:"Falta configurar la nómina",description:"Define días de trabajo pagados, horas por día y la tarifa predeterminada de hora extra.",tone:"info"});openSettings();return;}window.sessionStorage.setItem(activeAdjustmentKey,kind);setAdjustmentKind(kind);}
  function closeAdjustmentCapture(){window.sessionStorage.removeItem(activeAdjustmentKey);setAdjustmentKind(null);}
  async function saveOperationalSettings(){const payableDays=Number(settingsDraft.payableDays);const hoursPerWorkday=Number(settingsDraft.hoursPerWorkday);const defaultOvertimeHourlyRate=Number(settingsDraft.defaultOvertimeHourlyRate);if(!Number.isFinite(payableDays)||payableDays<=0||!Number.isFinite(hoursPerWorkday)||hoursPerWorkday<=0||!Number.isFinite(defaultOvertimeHourlyRate)||defaultOvertimeHourlyRate<=0){toast({title:"Revisa la configuración",description:"Define días de trabajo pagados, horas por día y una tarifa de hora extra mayores a cero.",tone:"error"});return;}setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("save_payroll_operational_configuration",{p_company_id:companyId,p_payment_frequency:schedule.payment_frequency,p_payable_days_per_period:payableDays,p_hours_per_workday:hoursPerWorkday,p_default_overtime_hourly_rate:defaultOvertimeHourlyRate});setSaving(false);if(rpcError){toast({title:"No se guardó la configuración",description:rpcError.message,tone:"error"});return;}setScheduleOpen(false);await load();toast({title:"Configuración actualizada",description:"Las nuevas horas extra usarán esta tarifa como valor predeterminado.",tone:"success"});}
  async function startCurrent(){setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("start_current_payroll",{p_company_id:companyId});setSaving(false);if(rpcError){toast({title:"No se pudo preparar la nómina",description:rpcError.message,tone:"error"});return;}setDetail(data as PeriodDetail);await load();toast({title:"Nómina preparada",description:"Revisa los importes antes de aprobar.",tone:"success"});}
  async function resolvePendingIncidents(action:"approve"|"reject"){if(!selectedIncidents.length)return;setSaving(true);const {error:rpcError}=await getSupabaseClient().rpc("resolve_payroll_incidents_batch",{p_company_id:companyId,p_movement_ids:selectedIncidents,p_action:action});setSaving(false);if(rpcError){toast({title:"No se actualizaron las incidencias",description:rpcError.message,tone:"error"});return;}const count=selectedIncidents.length;setSelectedIncidents([]);await load();if(detail)await openDetail(detail.id);toast({title:action==="approve"?"Incidencias aprobadas":"Incidencias rechazadas",description:`Se actualizaron ${count} incidencias.`,tone:"success"});}
  async function savePayrollLinePaymentMethod(){if(!linePaymentMethod||!detail)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("set_payroll_line_payment_method",{p_company_id:companyId,p_period_line_id:linePaymentMethod.lineId,p_payment_method:linePaymentMethod.paymentMethod});setSaving(false);if(rpcError){toast({title:"No se actualizó la forma de pago",description:rpcError.message,tone:"error"});return;}setLinePaymentMethod(null);setDetail(data as PeriodDetail);toast({title:"Forma de pago ajustada",description:"El cambio sólo aplica a esta corrida.",tone:"success"});}
  async function recordPaymentBatch(){if(!paymentBatch||!detail)return;setSaving(true);const {data,error:rpcError}=await getSupabaseClient().rpc("record_payroll_payment_batch",{p_company_id:companyId,p_period_id:detail.id,p_payment_method:paymentBatch.paymentMethod,p_payment_date:paymentBatch.paymentDate,p_payment_reference:paymentBatch.reference});setSaving(false);if(rpcError){toast({title:"No se registró el pago",description:rpcError.message,tone:"error"});return;}const method=paymentMethodLabel[paymentBatch.paymentMethod];setPaymentBatch(null);setDetail(data as PeriodDetail);await load();toast({title:"Pago registrado",description:`El grupo de ${method.toLowerCase()} quedó registrado.`,tone:"success"});}
  async function downloadPayrollReport(){if(!detail)return;try{const bytes=await createPayrollPeriodExcel({...detail,has_adjustments:detail.has_adjustments},detail.lines.map(line=>({...line,concepts:line.concepts.map(concept=>({...concept,calculation_metadata:concept.calculation_metadata as Record<string,unknown>|undefined}))})),detail.payment_batches);const blob=new Blob([bytes],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});const url=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=url;anchor.download=`nomina_${detail.starts_on}_${detail.ends_on}.xlsx`;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);}catch(value){toast({title:"No se generó el reporte",description:value instanceof Error?value.message:"Vuelve a intentarlo.",tone:"error"});}}
  async function advance(action:"prepare"|"recalculate"|"approve"){if(!detail)return;setSaving(true);const rpc=action==="approve"?"advance_payroll_period":"prepare_payroll_period";const params=action==="approve"?{p_company_id:companyId,p_period_id:detail.id,p_action:action,p_payment_reference:null}:{p_company_id:companyId,p_period_id:detail.id};const {data,error:rpcError}=await getSupabaseClient().rpc(rpc,params);setSaving(false);if(rpcError){toast({title:"No se actualizó la nómina",description:rpcError.message,tone:"error"});return;}setDetail(data as PeriodDetail);await load();toast({title:action==="approve"?"Nómina aprobada":action==="recalculate"?"Nómina recalculada":"Nómina preparada",description:action==="approve"?"Ahora registra los pagos agrupados por forma de pago.":action==="recalculate"?"El desglose ya incluye los movimientos aprobados más recientes.":"Revisa los importes antes de aprobar.",tone:"success"});}
  const activePeriod=current?.period??current?.proposed;
  const historyRows=rows.filter(row=>row.id!==current?.period?.id);
  const historyTotal=Math.max(total-(historyRows.length<rows.length?1:0),0);
  const detailApproval=detail?.approval??(detail?{available_on:previousDate(detail.ends_on),date_open:false,needs_recalculation:false,pending_movements:0}:null);
  const activePeriodAction=current?.period?()=>void openDetail(current.period!.id):()=>void startCurrent();
  const factorCards:Array<{kind:PayrollAdjustmentKind;label:string;description:string;amount:number;icon:typeof CircleDollarSign;tone:"addition"|"reduction"}>=[
    {kind:"overtime",label:"Horas extra",description:`Tarifa predeterminada ${money(settings.default_overtime_hourly_rate??50)} MXN/h`,amount:Number(workspace?.summary.overtime??0),icon:CircleDollarSign,tone:"addition"},
    {kind:"absence",label:"Inasistencias",description:"Descuento por días y horas",amount:Number(workspace?.summary.absences??0),icon:UserMinus,tone:"reduction"},
    {kind:"commission",label:"Comisiones",description:"Importes ligados a resultados",amount:Number(workspace?.summary.commissions??0),icon:TrendingUp,tone:"addition"},
    {kind:"bonus",label:"Bonificaciones",description:"Reconocimientos extraordinarios",amount:Number(workspace?.summary.bonuses??0),icon:Gift,tone:"addition"},
  ];
  if(loading&&!workspace)return <div className="content-frame collaborator-module payroll-module payroll-module--loading" aria-busy="true">
    <PageHeading eyebrow="Colaboradores · Nómina" title="Preparación de nómina" description="Captura movimientos, revisa el pago proyectado y prepara la nómina del periodo." action={<div className="payroll-loading-actions" aria-hidden="true"><i/><i/></div>}/>
    <section className="payroll-loading-current" aria-hidden="true"><div><i/><i/><i/></div><i/></section>
    <section className="payroll-loading-factors" aria-hidden="true"><i/><i/><i/><i/></section>
    <section className="payroll-loading-workspace" aria-hidden="true"><div><i/><i/><i/></div><i/><div><i/><i/><i/><i/><i/></div></section>
    <span className="sr-only" role="status" aria-live="polite">Cargando preparación de nómina…</span>
  </div>;
  return <div className="content-frame collaborator-module payroll-module">
    <PageHeading eyebrow="Colaboradores · Nómina" title="Preparación de nómina" description="Captura movimientos, revisa el pago proyectado y prepara la nómina del periodo." action={<div className="payroll-heading-actions">{canMove&&<Button variant="secondary" onClick={()=>{setSelectedIncidents([]);setPendingIncidentsPage(1);setPendingOpen(true);}}>Revisar pendientes{pendingIncidentsTotal?` (${pendingIncidentsTotal})`:""}</Button>}{canManage&&<Button variant="secondary" onClick={openSettings}><Settings2 size={16}/>Configurar nómina</Button>}</div>}/>
    <section className="payroll-current"><div><span className="eyebrow">Periodo vigente</span><strong>{activePeriod?`${date(activePeriod.starts_on)} – ${date(activePeriod.ends_on)}`:"Cargando periodo"}</strong><small>{activePeriod?frequencyLabel[activePeriod.payment_frequency]:""}</small></div>{canManage&&<Button variant="primary" loading={saving} onClick={activePeriodAction}><RefreshCw size={16}/>{current?.period?"Abrir nómina vigente":"Preparar nómina vigente"}</Button>}</section>
    {!incidentsReady&&<section className="payroll-guide"><Settings2 size={20}/><span>Configura días de trabajo pagados, horas por día y la tarifa predeterminada de hora extra.</span></section>}
    {canMove&&<section className="payroll-factor-grid" aria-label="Movimientos que modifican el sueldo base">{factorCards.map(card=>{const Icon=card.icon;return <button key={card.kind} type="button" className={`payroll-factor-card is-${card.tone}`} onClick={()=>openAdjustmentCapture(card.kind)}><span className="payroll-factor-card__icon"><Icon size={18} aria-hidden="true"/></span><span><strong>{card.label}</strong><small>{card.description}</small></span><span className="payroll-factor-card__amount">{card.tone==="reduction"&&card.amount>0?"−":card.amount>0?"+":""}{money(card.amount)}</span></button>;})}</section>}
    {workspace&&<section className="payroll-workspace" aria-labelledby="payroll-workspace-title">
      <div className="payroll-workspace__header"><div><span className="eyebrow">Vista previa del periodo</span><h2 id="payroll-workspace-title">Desglose por colaborador</h2><p>Incluye movimientos aprobados y pendientes; sólo los aprobados entrarán al preparar la nómina.</p></div><div className="payroll-workspace__total"><span>Pago proyectado</span><strong>{money(workspace.summary.estimated_pay)}</strong><small>{workspace.summary.pending_count} pendiente{workspace.summary.pending_count===1?"":"s"}</small></div></div>
      <DataToolbar search={workspaceQuery} onSearchChange={setWorkspaceQuery} placeholder="Buscar colaborador o código" results={workspace.pagination.total}/>
      <DataState loading={loading&&!workspace.items.length} error={error} hasData={workspace.items.length} empty="No hay colaboradores para este periodo."><Table className="payroll-workspace__table"><thead><tr><th>Colaborador</th><th>Sueldo base</th><th>Horas extra</th><th>Inasistencias</th><th>Comisiones</th><th>Bonificaciones</th><th>Pago proyectado</th></tr></thead><tbody>{workspace.items.map(line=><tr key={line.id}><td><strong>{line.display_name}</strong><small>{line.code}{line.pending_count?` · ${line.pending_count} pendiente${line.pending_count===1?"":"s"}`:""}</small></td><td>{money(line.base_pay)}</td><td className="is-addition">{line.overtime?`+${money(line.overtime)}`:"—"}</td><td className="is-reduction">{line.absences?`−${money(line.absences)}`:"—"}</td><td className="is-addition">{line.commissions?`+${money(line.commissions)}`:"—"}</td><td className="is-addition">{line.bonuses?`+${money(line.bonuses)}`:"—"}</td><td><strong>{money(line.estimated_pay)}</strong></td></tr>)}</tbody></Table><DataPagination page={workspacePage} onChange={setWorkspacePage} total={workspace.pagination.total} pageSize={workspace.pagination.page_size} label="colaboradores"/></DataState>
    </section>}
    {preflight&&<section className="payroll-readiness" aria-labelledby="payroll-readiness-title">
      <header className="payroll-readiness__header"><div><span className="eyebrow">Validación del periodo</span><h2 id="payroll-readiness-title">Antes de preparar la nómina</h2><p>Confirma que todos tengan sueldo vigente y que los movimientos estén revisados.</p></div><div className="payroll-readiness__total"><span>Pago proyectado</span><strong>{money(workspace?.summary.estimated_pay??preflight.estimated_total)}</strong></div></header>
      <div className="payroll-readiness__metrics">
        <article><span>Colaboradores incluidos</span><strong>{preflight.included}</strong></article>
        <article className={preflight.missing_compensation?"is-danger":"is-ready"}><span>Sin sueldo vigente</span><strong>{preflight.missing_compensation}</strong></article>
        <article className={preflight.pending_movements?"is-warning":"is-ready"}><span>Movimientos pendientes</span><strong>{preflight.pending_movements}</strong></article>
        <article className="is-ready"><span>Movimientos aprobados</span><strong>{preflight.approved_movements}</strong></article>
      </div>
      <div className="payroll-readiness__note"><CheckCircle2 size={18} aria-hidden="true"/><span>Captura movimientos, revisa pendientes y después prepara la nómina. El sueldo base no se modifica.</span></div>
    </section>}
    <section className="payroll-history" aria-labelledby="payroll-history-title">
      <header><span className="eyebrow">Periodos anteriores</span><h2 id="payroll-history-title">Historial de nómina</h2><p>Consulta periodos cerrados y abre cualquiera para revisar su desglose y los pagos registrados.</p></header>
      <DataState loading={loading&&!historyRows.length} error={error} hasData={historyRows.length} empty="Aún no hay periodos anteriores."><Table><thead><tr><th>Periodo</th><th>Registro de pago</th><th>Colaboradores</th><th>Total de nómina</th><th>Estado</th></tr></thead><tbody>{historyRows.map(row=>{const presentation=payrollPresentation(row);return <InteractiveTableRow key={row.id} label={`Abrir nómina ${date(row.starts_on)}`} onActivate={()=>void openDetail(row.id)}><td><strong>{date(row.starts_on)} – {date(row.ends_on)}</strong><small>{frequencyLabel[row.payment_frequency]} · Pago programado {date(row.payment_date)}</small></td><td>{row.payment_reference??"—"}</td><td>{row.collaborator_count}</td><td>{money(row.total_pay)}</td><td><Badge tone={presentation.tone}>{presentation.label}</Badge></td></InteractiveTableRow>})}</tbody></Table><DataPagination page={page} onChange={setPage} total={historyTotal} pageSize={pageSize} label="periodos"/></DataState>
    </section>
    <Modal open={scheduleOpen} onOpenChange={open=>!open&&!saving&&setScheduleOpen(false)} className="payroll-settings-dialog" eyebrow="Nómina" title="Configuración de nómina" description="Estas reglas se guardan por empresa y determinan los descuentos por inasistencia. La tarifa de hora extra puede cambiarse en cada registro." footer={<><Button disabled={saving} onClick={()=>setScheduleOpen(false)}>Cancelar</Button><Button variant="primary" loading={saving} onClick={()=>void saveOperationalSettings()}>Guardar configuración</Button></>}><div className="form-grid payroll-settings-grid"><Field label="Periodicidad" hint="Define cómo se agrupan los días en cada periodo de nómina."><Select ariaLabel="Periodicidad" value={schedule.payment_frequency} onValueChange={value=>setSchedule({payment_frequency:value as PayrollSchedule["payment_frequency"]})} options={[{value:"weekly",label:"Semanal"},{value:"biweekly",label:"Quincenal"},{value:"monthly",label:"Mensual"}]}/></Field><Field label="Días de trabajo pagados por periodo" hint="Se usa para calcular el sueldo diario. En una semana de seis días, captura 6."><Input required type="number" min="1" step="1" inputMode="numeric" value={settingsDraft.payableDays} onChange={event=>setSettingsDraft({...settingsDraft,payableDays:event.target.value})} placeholder="Ej. 6"/></Field><Field label="Horas por día de trabajo" hint="Define cuántas horas equivalen a un día completo. Ejemplo: 8."><Input required type="number" min="0.01" step="0.25" inputMode="decimal" value={settingsDraft.hoursPerWorkday} onChange={event=>setSettingsDraft({...settingsDraft,hoursPerWorkday:event.target.value})} placeholder="Ej. 8"/></Field><Field label="Tarifa predeterminada de hora extra" hint="Se precarga en cada fila; una edición individual no cambia este valor."><CurrencyInput required value={settingsDraft.defaultOvertimeHourlyRate} onValueChange={value=>setSettingsDraft({...settingsDraft,defaultOvertimeHourlyRate:value})} placeholder="50.00" aria-label="Tarifa predeterminada de hora extra"/></Field></div></Modal>
    {adjustmentKind&&workspace&&<PayrollAdjustmentModal companyId={companyId} kind={adjustmentKind} settings={settings} period={workspace.period} onClose={closeAdjustmentCapture} onSaved={async()=>{await load();if(detail)await openDetail(detail.id);}}/>}
    <PendingIncidentsModal open={pendingOpen} items={pendingIncidents} total={pendingIncidentsTotal} page={pendingIncidentsPage} selected={selectedIncidents} saving={saving} onClose={()=>setPendingOpen(false)} onToggle={id=>setSelectedIncidents(current=>current.includes(id)?current.filter(item=>item!==id):[...current,id])} onToggleAll={()=>setSelectedIncidents(current=>current.length===pendingIncidents.length?[]:pendingIncidents.map(item=>item.id))} onPageChange={next=>{setSelectedIncidents([]);setPendingIncidentsPage(next);}} onResolve={action=>void resolvePendingIncidents(action)}/>
    <Drawer open={Boolean(detail)} onOpenChange={open=>!open&&!saving&&setDetail(null)} title={detail?`Nómina · ${date(detail.starts_on)} – ${date(detail.ends_on)}`:"Nómina"} className="payroll-detail">{detail&&<>
      <div className="payroll-detail__chrome">
        <div className="payroll-detail__summary"><article><span>Total de nómina</span><strong>{money(detail.totals.total_pay)}</strong></article><article><span>Colaboradores</span><strong>{detail.lines.length}</strong></article>{(()=>{const presentation=payrollPresentation(detail);return <Badge tone={presentation.tone}>{presentation.label}</Badge>;})()}<Button size="sm" variant="secondary" onClick={()=>void downloadPayrollReport()}><Download size={15} aria-hidden="true"/>Exportar reporte</Button></div>
        {detail.status==="draft"&&canManage&&<section className="payroll-action-card"><div><strong>Lista para preparar</strong><span>Calcula el sueldo base proporcional y toma sólo los movimientos aprobados del corte.</span></div><Button variant="primary" loading={saving} onClick={()=>void advance("prepare")}><RefreshCw size={16}/>Preparar nómina</Button></section>}
        {detail.status==="reviewing"&&canApprove&&detailApproval?.needs_recalculation&&<section className="payroll-action-card payroll-action-card--attention"><div><strong>Recalcula antes de aprobar</strong><span>Hay movimientos aprobados que todavía no aparecen en este desglose.</span></div><Button variant="primary" loading={saving} onClick={()=>void advance("recalculate")}><RefreshCw size={16} aria-hidden="true"/>Recalcular nómina</Button></section>}
        {detail.status==="reviewing"&&canApprove&&!detailApproval?.needs_recalculation&&Number(detailApproval?.pending_movements)>0&&<section className="payroll-action-card payroll-action-card--attention"><div><strong>Revisa los movimientos pendientes</strong><span>{detailApproval?.pending_movements} movimiento{detailApproval?.pending_movements===1?" necesita":"s necesitan"} una decisión antes de aprobar.</span></div><Button variant="secondary" onClick={()=>{setSelectedIncidents([]);setPendingIncidentsPage(1);setPendingOpen(true);}}>Revisar pendientes</Button></section>}
        {detail.status==="reviewing"&&canApprove&&!detailApproval?.needs_recalculation&&Number(detailApproval?.pending_movements)===0&&!detailApproval?.date_open&&<section className="payroll-action-card"><div><strong>La revisión continúa abierta</strong><span>Podrás aprobar la nómina desde el {date(detailApproval?.available_on)}, un día antes de cerrar el periodo.</span></div><Button variant="secondary" disabled><CalendarDays size={16} aria-hidden="true"/>Disponible el {date(detailApproval?.available_on)}</Button></section>}
        {detail.status==="reviewing"&&canApprove&&!detailApproval?.needs_recalculation&&Number(detailApproval?.pending_movements)===0&&detailApproval?.date_open&&<section className="payroll-action-card"><div><strong>Revisión final</strong><span>Al aprobar, los movimientos utilizados no podrán modificarse; un ajuste irá al siguiente periodo.</span></div><Button variant="primary" loading={saving} onClick={()=>void advance("approve")}><CheckCircle2 size={16} aria-hidden="true"/>Aprobar nómina</Button></section>}
        {(detail.status==="approved"||detail.status==="paid")&&<PayrollPaymentGroups detail={detail} saving={saving} canRecord={detail.status==="approved"&&canPay} onLineMethod={line=>setLinePaymentMethod({lineId:line.id,collaboratorName:line.collaborator_name_snapshot,paymentMethod:line.payment_method==="cash"||line.payment_method==="other"?line.payment_method:"transfer"})} onRecord={method=>setPaymentBatch(emptyPaymentBatch(method))}/>}
      </div>
      {detail.status!=="draft"&&<Table className="payroll-detail__table payroll-breakdown-table"><thead><tr><th>Colaborador</th><th>Sueldo base</th><th>Horas extra</th><th>Inasistencias</th><th>Comisiones</th><th>Bonificaciones</th><th>Pago neto</th></tr></thead><tbody>{detail.lines.map(line=>{const overtime=conceptAmount(line,"overtime");const absences=conceptAmount(line,"absence");const commissions=conceptAmount(line,"commission");const bonuses=conceptAmount(line,"bonus");return <tr key={line.id}><td data-label="Colaborador"><strong>{line.collaborator_name_snapshot}</strong><small>{line.concepts.filter(item=>item.concept_code!=="base_pay").map(item=>{const calculation=calculationLabel(item);return `${item.label}: ${item.direction==="reduction"?"−":"+"}${money(item.amount)}${calculation?` (${calculation})`:""}`;}).join(" · ")||"Sin movimientos"}</small></td><td data-label="Sueldo base">{money(line.base_pay_snapshot)}</td><td data-label="Horas extra" className="is-addition">{overtime?`+${money(overtime)}`:"—"}</td><td data-label="Inasistencias" className="is-reduction">{absences?`−${money(absences)}`:"—"}</td><td data-label="Comisiones" className="is-addition">{commissions?`+${money(commissions)}`:"—"}</td><td data-label="Bonificaciones" className="is-addition">{bonuses?`+${money(bonuses)}`:"—"}</td><td data-label="Pago neto"><strong>{money(line.total_pay)}</strong></td></tr>;})}</tbody></Table>}
    </>}</Drawer>
    <PayrollLinePaymentMethodModal draft={linePaymentMethod} saving={saving} onChange={setLinePaymentMethod} onClose={()=>setLinePaymentMethod(null)} onSave={()=>void savePayrollLinePaymentMethod()}/>
    <PayrollPaymentBatchModal draft={paymentBatch} saving={saving} onChange={setPaymentBatch} onClose={()=>setPaymentBatch(null)} onSave={()=>void recordPaymentBatch()}/>
  </div>;
}

function PaymentMethodModal({draft,saving,onChange,onClose,onSave}:{draft:PaymentMethodDraft|null;saving:boolean;onChange:(draft:PaymentMethodDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Colaborador" title="Forma de pago predeterminada" description="Se conservará en el expediente y se propondrá al registrar el pago de una corrida." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} onClick={onSave}>Guardar</Button></>}>{draft&&<Field label="Forma de pago"><Select ariaLabel="Forma de pago" value={draft.paymentMethod} onValueChange={value=>onChange({...draft,paymentMethod:value as PaymentMethod})} options={[{value:"unspecified",label:"Sin definir"},{value:"transfer",label:"Transferencia"},{value:"cash",label:"Efectivo"},{value:"other",label:"Otro"}]}/></Field>}</Modal>}
/* Captura anterior conservada temporalmente sólo como referencia durante la migración.
function IncidentBatchModal({companyId,draft,saving,settings,onChange,onClose,onSave}:{companyId:string;draft:IncidentBatchDraft|null;saving:boolean;settings:OperationalSettings;onChange:(draft:IncidentBatchDraft|null)=>void;onClose:()=>void;onSave:()=>void}){
  if(draft?.kind==="overtime")return <OvertimeIncidentModal companyId={companyId} draft={draft} saving={saving} settings={settings} onChange={next=>onChange(next)} onClose={onClose} onSave={onSave}/>;
  return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Nómina · Incidencias" title="Capturar inasistencias" description="Una inasistencia pagada queda registrada sin descuento; una no pagada descuenta días al valor diario vigente." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} onClick={onSave}>Capturar incidencias</Button></>}>{draft&&<div className="batch-movement-form"><div className="payroll-guide"><CircleDollarSign size={18}/><span>Fórmula de descuento: valor diario × días. Usa “pagada” o “no_pagada” en cada renglón.</span></div><label className="operation-reason">Un renglón por colaborador: código [tab] inicio [tab] fin [tab] días [tab] pagada/no_pagada [tab] descripción<textarea value={draft.rows} onChange={event=>onChange({...draft,rows:event.target.value})} rows={8} placeholder={"COL-000001\t2026-07-25\t2026-07-25\t1\tno_pagada\tFalta\nCOL-000002\t2026-07-25\t2026-07-25\t1\tpagada\tPermiso autorizado"}/></label><label className="checkbox-field"><input type="checkbox" checked={draft.approve} onChange={event=>onChange({...draft,approve:event.target.checked})}/> Aprobar ahora para incluirlas en nómina</label><small>Hasta 100 renglones por lote. Se valida y guarda todo el lote o no se guarda nada.</small></div>}</Modal>;
}

function OvertimeIncidentModal({companyId,draft,saving,settings,onChange,onClose,onSave}:{companyId:string;draft:OvertimeIncidentBatchDraft;saving:boolean;settings:OperationalSettings;onChange:(draft:OvertimeIncidentBatchDraft)=>void;onClose:()=>void;onSave:()=>void}){
  const [query,setQuery]=useState("");const [debounced,setDebounced]=useState("");const [options,setOptions]=useState<Collaborator[]>([]);const [searching,setSearching]=useState(false);const [searchOpen,setSearchOpen]=useState(false);const [searchError,setSearchError]=useState<string|null>(null);
  const [defaultDate,setDefaultDate]=useState(new Date().toISOString().slice(0,10));const [defaultMultiplier,setDefaultMultiplier]=useState(settings.overtime_multipliers[0]===undefined?"":String(settings.overtime_multipliers[0]));const searchRequest=useRef(0);
  useEffect(()=>{const timer=window.setTimeout(()=>{const next=query.trim();setDebounced(next);setSearching(next.length>=2);},250);return()=>window.clearTimeout(timer);},[query]);
  useEffect(()=>{if(debounced.length<2)return;const current=++searchRequest.current;void getSupabaseClient().rpc("search_collaborators",{p_company_id:companyId,p_query:debounced,p_status:"active",p_page:1,p_page_size:20}).then(({data,error})=>{if(current!==searchRequest.current)return;setSearching(false);if(error){setSearchError(error.message);setOptions([]);return;}setSearchError(null);setOptions((data as {items?:Collaborator[]}|null)?.items??[]);});},[companyId,debounced]);
  function updateRow(id:string,patch:Partial<OvertimeIncidentRow>){onChange({...draft,rows:draft.rows.map(row=>row.id===id?{...row,...patch}:row)});}
  function addCollaborator(collaborator:Collaborator){if(draft.rows.length>=100){setSearchError("El lote admite hasta 100 colaboradores.");return;}onChange({...draft,rows:[...draft.rows,{id:crypto.randomUUID(),collaboratorId:collaborator.id,collaboratorCode:collaborator.code,collaboratorName:collaborator.display_name,basePayAmount:collaborator.base_pay_amount,compensationEffectiveFrom:collaborator.effective_from,effectiveOn:defaultDate,hours:"",multiplier:defaultMultiplier,description:""}]});setQuery("");setDebounced("");setOptions([]);setSearchOpen(false);setSearchError(null);}
  function applyDefaults(){onChange({...draft,rows:draft.rows.map(row=>({...row,effectiveOn:defaultDate,multiplier:defaultMultiplier}))});}
  function requestSave(){const invalid=draft.rows.find(row=>!row.effectiveOn||!Number.isFinite(Number(row.hours))||Number(row.hours)<=0||!settings.overtime_multipliers.includes(Number(row.multiplier)));if(invalid){document.getElementById(`overtime-hours-${invalid.id}`)?.focus();}onSave();}
  const previews=draft.rows.map(row=>{const hours=Number(row.hours);const multiplier=Number(row.multiplier);const equivalent=Number.isFinite(hours)&&hours>0&&Number.isFinite(multiplier)?hours*multiplier:0;const hasApplicableRate=Boolean(row.basePayAmount!==null&&row.compensationEffectiveFrom&&row.effectiveOn&&row.compensationEffectiveFrom<=row.effectiveOn&&settings.payable_days_per_period&&settings.hours_per_workday);const hourlyRate=hasApplicableRate?Number(row.basePayAmount)/Number(settings.payable_days_per_period)/Number(settings.hours_per_workday):null;return {equivalent,hourlyRate,amount:hourlyRate===null?null:hourlyRate*equivalent};});
  const actualHours=draft.rows.reduce((total,row)=>total+(Number.isFinite(Number(row.hours))?Number(row.hours):0),0);const equivalentHours=previews.reduce((total,item)=>total+item.equivalent,0);const completeEstimate=draft.rows.length>0&&previews.every(item=>item.amount!==null);const estimatedAmount=previews.reduce((total,item)=>total+(item.amount??0),0);const visibleOptions=options.filter(item=>!draft.rows.some(row=>row.collaboratorId===item.id));
  return <Modal open onOpenChange={open=>!open&&!saving&&onClose()} className="payroll-overtime-dialog" eyebrow="Nómina · Incidencias" title="Agregar horas extra" description="Captura las horas reales. Satrapy muestra las horas equivalentes y estima el importe antes de guardar." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} onClick={requestSave}>Guardar como pendientes</Button></>}>
    <div className="overtime-capture">
      <div className="payroll-guide"><CircleDollarSign size={18}/><span>La tarifa corresponde al pago vigente en la fecha trabajada. Los factores autorizados son <strong>{settings.overtime_multipliers.map(value=>`×${value}`).join(", ")}</strong>; son factores de pago, no porcentajes.</span></div>
      <section className="overtime-capture__defaults" aria-labelledby="overtime-defaults-title">
        <div><strong id="overtime-defaults-title">Agregar colaboradores</strong><small>Busca por nombre o código. La fecha y el factor se aplican a las filas nuevas.</small></div>
        <div className="overtime-capture__controls">
          <div className="overtime-collaborator-search">
            <label htmlFor="overtime-collaborator-query">Colaborador</label>
            <div><Search size={15} aria-hidden="true"/><Input id="overtime-collaborator-query" value={query} onFocus={()=>setSearchOpen(true)} onBlur={()=>window.setTimeout(()=>setSearchOpen(false),120)} onChange={event=>{setQuery(event.target.value);setSearchOpen(true);setSearchError(null);}} placeholder="Escribe nombre o código" autoComplete="off"/></div>
            {searchOpen&&query.trim().length>=2&&<div className="overtime-collaborator-results">{searching?<p role="status">Buscando colaboradores…</p>:visibleOptions.length?visibleOptions.map(option=><button type="button" key={option.id} onMouseDown={event=>event.preventDefault()} onClick={()=>addCollaborator(option)}><span><strong>{option.display_name}</strong><small>{option.code}{option.position_name?` · ${option.position_name}`:""}</small></span><Plus size={15} aria-hidden="true"/></button>):<p>{searchError??"No hay colaboradores activos que coincidan."}</p>}</div>}
          </div>
          <Field label="Fecha del movimiento"><Input type="date" value={defaultDate} onChange={event=>setDefaultDate(event.target.value)} aria-label="Fecha del movimiento"/></Field>
          <Field label="Factor para nuevas filas"><Select ariaLabel="Factor para nuevas filas" value={defaultMultiplier} onValueChange={setDefaultMultiplier} options={settings.overtime_multipliers.map(value=>({value:String(value),label:`×${value}`}))}/></Field>
          <Button size="sm" variant="secondary" disabled={!draft.rows.length||!defaultDate||!defaultMultiplier} onClick={applyDefaults}>Aplicar a todas</Button>
        </div>
        {searchError&&<small className="overtime-capture__search-error" role="alert">{searchError}</small>}
      </section>
      {draft.rows.length?<div className="overtime-capture__table"><table><thead><tr><th>Colaborador</th><th>Fecha trabajada</th><th>Horas reales</th><th>Factor</th><th>Vista previa</th><th>Descripción</th><th aria-label="Acciones"></th></tr></thead><tbody>{draft.rows.map((row,index)=>{const preview=previews[index];const invalidHours=row.hours!==""&&(!Number.isFinite(Number(row.hours))||Number(row.hours)<=0);const missingRate=preview.hourlyRate===null;return <tr key={row.id}><td data-label="Colaborador"><strong>{row.collaboratorName}</strong><small>{row.collaboratorCode}</small></td><td data-label="Fecha trabajada"><Input type="date" value={row.effectiveOn} onChange={event=>updateRow(row.id,{effectiveOn:event.target.value})} aria-label={`Fecha trabajada de ${row.collaboratorName}`}/></td><td data-label="Horas reales"><Input id={`overtime-hours-${row.id}`} type="number" min="0.01" step="0.25" inputMode="decimal" value={row.hours} onChange={event=>updateRow(row.id,{hours:event.target.value})} aria-label={`Horas reales de ${row.collaboratorName}`} aria-invalid={invalidHours||undefined} aria-describedby={invalidHours?`overtime-error-${row.id}`:undefined}/>{invalidHours&&<small id={`overtime-error-${row.id}`} className="overtime-row-error">Captura horas mayores a cero.</small>}</td><td data-label="Factor"><Select ariaLabel={`Factor de ${row.collaboratorName}`} value={row.multiplier} onValueChange={value=>updateRow(row.id,{multiplier:value})} options={settings.overtime_multipliers.map(value=>({value:String(value),label:`×${value}`}))}/></td><td data-label="Vista previa"><div className="overtime-preview" role="status"><strong>{preview.equivalent?`${Number(row.hours)} h × ${row.multiplier} = ${preview.equivalent} h`:"Completa las horas"}</strong><small>{preview.amount!==null&&preview.equivalent?`${money(preview.hourlyRate)}/h × ${preview.equivalent} = ${money(preview.amount)}`:missingRate?"La tarifa se confirmará al guardar.":"Importe por calcular"}</small></div></td><td data-label="Descripción"><Input value={row.description} onChange={event=>updateRow(row.id,{description:event.target.value})} placeholder="Ej. Turno de cierre" aria-label={`Descripción de ${row.collaboratorName}`}/></td><td className="overtime-capture__remove"><Button type="button" size="icon" variant="ghost" aria-label={`Quitar a ${row.collaboratorName}`} onClick={()=>onChange({...draft,rows:draft.rows.filter(item=>item.id!==row.id)})}><Trash2 size={15}/></Button></td></tr>;})}</tbody></table></div>:<div className="overtime-capture__empty"><Search size={20} aria-hidden="true"/><strong>Agrega colaboradores para comenzar</strong><span>Satrapy calculará cada fila sin depender de archivos externos.</span></div>}
      <section className="overtime-capture__summary" aria-label="Resumen del lote"><div><span>Colaboradores</span><strong>{draft.rows.length}</strong></div><div><span>Horas trabajadas</span><strong>{actualHours.toLocaleString("es-MX",{maximumFractionDigits:2})} h</strong></div><div><span>Horas equivalentes</span><strong>{equivalentHours.toLocaleString("es-MX",{maximumFractionDigits:2})} h</strong></div><div><span>Importe estimado</span><strong>{completeEstimate?money(estimatedAmount):"Por confirmar"}</strong></div></section>
      <small className="overtime-capture__note">El cálculo definitivo se valida en el servidor al guardar. Las incidencias quedarán pendientes hasta que se aprueben desde Nómina.</small>
    </div>
  </Modal>;
}
*/
function PendingIncidentsModal({open,items,total,page,selected,saving,onClose,onToggle,onToggleAll,onPageChange,onResolve}:{open:boolean;items:PendingIncident[];total:number;page:number;selected:string[];saving:boolean;onClose:()=>void;onToggle:(id:string)=>void;onToggleAll:()=>void;onPageChange:(page:number)=>void;onResolve:(action:"approve"|"reject")=>void}){const allSelected=items.length>0&&selected.length===items.length;return <Modal open={open} onOpenChange={value=>!value&&!saving&&onClose()} eyebrow="Nómina · Revisión" title="Movimientos pendientes" description="Aprueba o rechaza los movimientos seleccionados. Sólo los aprobados entran a la nómina." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="danger" loading={saving} disabled={!selected.length} onClick={()=>onResolve("reject")}>Rechazar seleccionados</Button><Button variant="primary" loading={saving} disabled={!selected.length} onClick={()=>onResolve("approve")}>Aprobar seleccionados</Button></>}>{items.length?<div className="pending-incidents"><label className="checkbox-field"><input aria-label="Seleccionar todos los movimientos" type="checkbox" checked={allSelected} onChange={onToggleAll}/> Seleccionar los {items.length} movimientos mostrados</label><Table><thead><tr><th></th><th>Colaborador</th><th>Movimiento</th><th>Cálculo</th><th>Importe</th></tr></thead><tbody>{items.map(item=>{const calculation=calculationLabel({concept_code:item.movement_type,calculation_metadata:item.calculation_metadata});return <tr key={item.id}><td><input aria-label={`Seleccionar movimiento de ${item.collaborator_name}`} type="checkbox" checked={selected.includes(item.id)} onChange={()=>onToggle(item.id)}/></td><td><strong>{item.collaborator_name}</strong><small>{item.collaborator_code}</small></td><td><strong>{movementLabel(item.movement_type)}</strong><small>{date(item.effective_on)}{item.description?` · ${item.description}`:""}</small></td><td><small>{calculation||"Importe capturado"}</small></td><td><strong className={item.movement_type==="absence"?"is-reduction":""}>{item.movement_type==="absence"?"−":"+"}{money(item.amount)}</strong></td></tr>;})}</tbody></Table><DataPagination page={page} onChange={onPageChange} total={total} pageSize={100} label="movimientos pendientes"/></div>:<div className="payroll-guide"><CheckCircle2 size={18}/><span>No hay movimientos pendientes por revisar.</span></div>}</Modal>}
function PayrollPaymentGroups({detail,saving,canRecord,onLineMethod,onRecord}:{detail:PeriodDetail;saving:boolean;canRecord:boolean;onLineMethod:(line:PeriodLine)=>void;onRecord:(method:PayablePaymentMethod)=>void}){const methods:PaymentMethod[]=["transfer","cash","other","unspecified"];const batches=new Map((detail.payment_batches??[]).map(batch=>[batch.payment_method,batch]));const groups=methods.map(method=>({method,lines:detail.lines.filter(line=>(line.payment_method??"unspecified")===method&&Number(line.total_pay)!==0)})).filter(group=>group.lines.length);return <section className="payroll-payment-groups"><div><strong>Pagos por método</strong><span>{canRecord?"Registra cada grupo con su propia fecha y referencia. La corrida se cierra al registrar todos los grupos.":"Fechas reales, referencias e importes registrados para esta nómina."}</span></div>{groups.map(group=>{const total=group.lines.reduce((sum,line)=>sum+Number(line.total_pay),0);const batch=group.method==="unspecified"?null:batches.get(group.method);return <article key={group.method}><div><span>{paymentMethodLabel[group.method]}</span><strong>{money(total)}</strong><small>{group.lines.length} colaborador{group.lines.length===1?"":"es"}</small></div>{group.method==="unspecified"?<div className="payroll-payment-groups__undefined"><small>Asigna una forma de pago para poder registrar este grupo.</small>{canRecord&&group.lines.map(line=><Button key={line.id} size="sm" variant="secondary" disabled={saving} onClick={()=>onLineMethod(line)}>Asignar a {line.collaborator_name_snapshot}</Button>)}</div>:batch?<div className="payroll-payment-groups__recorded"><Badge tone="success">Pagado</Badge><small>{date(batch.payment_date)} · {batch.payment_reference}</small></div>:canRecord?<Button size="sm" variant="primary" loading={saving} onClick={()=>onRecord(group.method as PayablePaymentMethod)}><WalletCards size={15}/>Registrar pago</Button>:null}</article>;})}</section>}
function PayrollLinePaymentMethodModal({draft,saving,onChange,onClose,onSave}:{draft:PayrollLinePaymentMethodDraft|null;saving:boolean;onChange:(draft:PayrollLinePaymentMethodDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Pago" title="Forma de pago para esta corrida" description="Es una excepción de esta nómina; no modifica la forma predeterminada del colaborador." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} onClick={onSave}>Guardar excepción</Button></>}>{draft&&<div className="form-grid"><Field label="Colaborador"><Input value={draft.collaboratorName} disabled/></Field><Field label="Forma de pago"><Select ariaLabel="Forma de pago de la corrida" value={draft.paymentMethod} onValueChange={value=>onChange({...draft,paymentMethod:value as PayablePaymentMethod})} options={[{value:"transfer",label:"Transferencia"},{value:"cash",label:"Efectivo"},{value:"other",label:"Otro"}]}/></Field></div>}</Modal>}
function PayrollPaymentBatchModal({draft,saving,onChange,onClose,onSave}:{draft:PaymentBatchDraft|null;saving:boolean;onChange:(draft:PaymentBatchDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Pago" title={draft?`Registrar pago · ${paymentMethodLabel[draft.paymentMethod]}`:"Registrar pago"} description="La referencia se conserva para este grupo de pago y no puede modificarse al cerrar la nómina." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.paymentDate||!draft.reference.trim()} onClick={onSave}>Registrar pago</Button></>}>{draft&&<div className="form-grid"><Field label="Fecha de pago"><Input required type="date" value={draft.paymentDate} onChange={event=>onChange({...draft,paymentDate:event.target.value})}/></Field><Field label="Referencia / comprobante"><Input required value={draft.reference} onChange={event=>onChange({...draft,reference:event.target.value})} placeholder="Ej. Folio o comprobante"/></Field></div>}</Modal>}
function MovementModal({draft,saving,onChange,onClose,onSave}:{draft:MovementDraft|null;saving:boolean;onChange:(draft:MovementDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Movimiento" title="Registrar otro concepto" description="Registra bonos, aguinaldo, prima vacacional u otros ajustes. Horas extra e inasistencias se calculan desde Nómina." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.amount||!draft.effectiveOn} onClick={onSave}>Guardar movimiento</Button></>}>{draft&&<div className="form-grid"><Field label="Concepto"><Select ariaLabel="Concepto" value={draft.movementType} onValueChange={value=>onChange({...draft,movementType:value})} options={[{value:"bonus",label:"Bono"},{value:"aguinaldo",label:"Aguinaldo"},{value:"vacation_premium",label:"Prima vacacional"},{value:"adjustment",label:"Ajuste"}]}/></Field><Field label="Tratamiento"><Select ariaLabel="Tratamiento" value={draft.direction} onValueChange={value=>onChange({...draft,direction:value as MovementDraft["direction"]})} options={[{value:"addition",label:"Suma al pago"},{value:"reduction",label:"Resta al pago"},{value:"informational",label:"Sólo informativo"}]}/></Field><Field label="Fecha efectiva"><Input type="date" value={draft.effectiveOn} onChange={event=>onChange({...draft,effectiveOn:event.target.value})}/></Field><Field label="Unidades"><Input type="number" min="0" step="0.01" value={draft.units} onChange={event=>onChange({...draft,units:event.target.value})}/></Field><Field label="Importe"><Input type="number" min="0" step="0.01" value={draft.amount} onChange={event=>onChange({...draft,amount:event.target.value})}/></Field><Field label="Descripción"><Input value={draft.description} onChange={event=>onChange({...draft,description:event.target.value})}/></Field><label className="checkbox-field"><input type="checkbox" checked={draft.approve} onChange={event=>onChange({...draft,approve:event.target.checked})}/> Aprobar ahora para incluirlo en nómina</label></div>}</Modal>}
