function VacationBalanceModal({draft,saving,onChange,onClose,onSave}:{draft:VacationBalanceDraft|null;saving:boolean;onChange:(draft:VacationBalanceDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Vacaciones" title="Ajustar saldo anual" description="Los días usados se calculan desde las vacaciones aprobadas; aquí sólo se configura lo otorgado y cualquier ajuste justificado." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="primary" loading={saving} disabled={!draft?.year||!draft.grantedDays} onClick={onSave}>Guardar saldo</Button></>}>{draft&&<div className="form-grid"><Field label="Año"><Input type="number" min="2000" max="2200" value={draft.year} onChange={event=>onChange({...draft,year:event.target.value})}/></Field><Field label="Días otorgados"><Input type="number" min="0" step="0.5" value={draft.grantedDays} onChange={event=>onChange({...draft,grantedDays:event.target.value})}/></Field><Field label="Ajuste de días"><Input type="number" step="0.5" value={draft.adjustmentDays} onChange={event=>onChange({...draft,adjustmentDays:event.target.value})}/></Field><Field label="Motivo / nota"><Input value={draft.notes} onChange={event=>onChange({...draft,notes:event.target.value})}/></Field></div>}</Modal>}
function TerminationModal({draft,saving,onChange,onClose,onSave}:{draft:TerminationDraft|null;saving:boolean;onChange:(draft:TerminationDraft|null)=>void;onClose:()=>void;onSave:()=>void}){return <Modal open={Boolean(draft)} onOpenChange={open=>!open&&!saving&&onClose()} eyebrow="Colaborador" title="Dar de baja" description="El expediente y los pagos históricos se conservan. Desde esta fecha no se incluirá en periodos posteriores." footer={<><Button disabled={saving} onClick={onClose}>Cancelar</Button><Button variant="danger" loading={saving} disabled={!draft?.terminatedAt||!draft.reason.trim()} onClick={onSave}>Confirmar baja</Button></>}>{draft&&<div className="form-grid"><Field label="Colaborador"><Input value={draft.displayName} disabled/></Field><Field label="Fecha de baja"><Input required type="date" min={draft.hiredAt} value={draft.terminatedAt} onChange={event=>onChange({...draft,terminatedAt:event.target.value})}/></Field><Field label="Motivo"><Input required value={draft.reason} onChange={event=>onChange({...draft,reason:event.target.value})} placeholder="Ej. Terminación de relación laboral"/></Field></div>}</Modal>}
function movementLabel(type:string){return type==="overtime"?"Horas extra":type==="commission"?"Comisiones":type==="bonus"?"Bonificaciones":type==="aguinaldo"?"Aguinaldo":type==="vacation_premium"?"Prima vacacional":type==="absence"?"Inasistencias":"Ajuste";}
